/**
 * workflow-gates — the agentic-workflows engine's gates drawn above the
 * prompt instead of printed by the model.
 *
 * The engine states each gate as data beside the menu it composed. This
 * module announces itself so the engine collects it, arms the gate off the
 * Bash result that carried it, cuts the menu out of what the model reads, and
 * draws the rows in the band once the model's turn is over. A press picks its
 * row's answer into the prompt box; a second press on that row sends it as the
 * next message, which the workflows' prose reads as the answer, or while
 * Claude works on anything else holds it until Claude finishes. In a session
 * that announced, what the band shows is kept in the conversation's folder
 * across a restart, so a conversation resumed where nothing has happened
 * since shows its gate again.
 *
 * Every path up to the cut fails open: the engine emits the menu regardless,
 * so where the module never loads, or a cut throws or overruns, the model
 * reads the text menu the engine wrote.
 *
 * The module carries the workflows' handoffs too: a move into work the engine
 * names arms off the Bash result that carried it, cut out of what the model
 * reads, and once the turn ends the module clears the conversation and sends
 * the continuation into the new one, an Esc on that turn carrying nothing.
 *
 * The module also sets Claude Code's harness for the workflows: every session
 * gets the SendUserMessage tool, kept behind ToolSearch, and a conversation
 * the engine has marked as running the workflows goes without Claude's
 * thinking summarised as output and without the nudge to say what it is
 * doing, the person's own values of both put back as it ends. A conversation
 * the engine has not marked keeps them untouched.
 *
 * All of it happens in Claude Code's terminal app and the Desktop app's Code
 * tab alone, from 2.1.287. Elsewhere — the VS Code extension, Claude Code on
 * the web, an older Claude Code — the session is not announced, and the
 * module draws, keeps and sets nothing.
 */
import type {
  AgentLoop,
  EngineInterface,
  PromptOrigin,
  Register,
  RenderSurface,
  SessionMessage,
} from 'claude-code'

import {
  IDLE,
  NO_SENDS,
  answerOf,
  linesOf,
  type Gate,
  type Option,
  type Sends,
} from './layout.ts'

/** The payload's marker and the menu it sits directly above. */
const GATE_MARKER = '=== GATE ('
const MENU_MARKER = '=== MENU'
const SECTION_MARKER = '=== '

/** The marker of a handoff's payload. */
const HANDOFF_MARKER = '=== HANDOFF ('

/** The `Client`'s key: what `ui.message` matches the board's posts on. */
const ELEMENT = 'gate'

/**
 * The file in the conversation's folder where a send leaves what it answered,
 * for a mod that draws the sent row.
 */
const SENT = 'sent.json'

/** The record that claims no send, which that mod draws nothing from. */
const NOTHING_SENT = 'null'

/**
 * What a send leaves in the conversation's folder: the answer to a gate, with
 * the question and the row's label; or a handoff's continuation, with the line
 * naming where the work went.
 */
type Sent =
  | { answer: string; question: string; label: string }
  | { answer: string; line: string }

/** A move into work the engine named: the continuation to send, and its line. */
type Handoff = { text: string; line: string }

/** How long a continuation the mod could not carry stays on screen to send. */
const UNCARRIED_TOAST_MS = 30_000

/**
 * Where each conversation that runs the workflows keeps what belongs to it,
 * in the workflows' system config directory.
 */
const CONVERSATIONS = 'conversations'

/** The file the engine marks a conversation that runs the workflows with. */
const MARKER = 'workflow'

/** The file a conversation's band is kept in for a resume. */
const KEPT = 'gate.json'

/**
 * The entrypoints the mod runs under, as the engine's boot reads them:
 * Claude Code's terminal app, and the Desktop app's Code tab on Anthropic's
 * API or a third-party provider.
 */
const ENTRYPOINTS: ReadonlySet<string> = new Set([
  'cli',
  'claude-desktop',
  'claude-desktop-3p',
])

/** The surfaces the band draws on: the terminal app's, and the Desktop app's. */
const BAND_SURFACES: ReadonlySet<RenderSurface> = new Set(['terminal', 'desktop'])

/** The oldest Claude Code the mod runs on, major, minor and patch. */
const OLDEST = [2, 1, 287]

/** A release's version, as `claude --version` prints it. */
const RELEASE = /^(\d+)\.(\d+)\.(\d+)$/

const STOP_NOTE =
  "The options are on screen as buttons. The user's answer arrives as their next message — typed by them, or sent for them by the workflow-gates plugin when they press a row."

/**
 * What the band holds of the conversation's gates. A turn the person starts
 * clears all of it but the gate that turn answers; a turn anyone else starts
 * leaves it as it is; the conversation's end clears all.
 */
type Band = {
  /** The gate a render armed, waiting on the end of its turn. */
  armed: Gate | null
  /** The gate on the band, from a turn's end to a turn the person starts. */
  drawn: Gate | null
  /** The answer a press put in the prompt box: a press on its row sends it. */
  picked: string | null
  /** The answer held to send when Claude finishes, and one a gate dropped. */
  sends: Sends
  /**
   * Whether the submission that opens the next turn is the person's; a turn
   * no submission opened counts as theirs.
   */
  isOpenedByPerson: boolean
  /** Whose the running turn is, the person's or anyone else's; null idle. */
  running: 'person' | 'other' | null
  /** The gate on the band when the person's running turn began. */
  answering: Gate | null
  /** Whether the running turn has called a tool. */
  hasCalledTool: boolean
}

const emptyBand = (): Band => ({
  armed: null,
  drawn: null,
  picked: null,
  sends: NO_SENDS,
  isOpenedByPerson: true,
  running: null,
  answering: null,
  hasCalledTool: false,
})

/**
 * What a turn's end leaves for the prompt box: a held answer's row, sent now
 * or handed back as a pick; and the text of a pick whose gate went, which
 * the box may still hold.
 */
type Settled = {
  held: { option: Option; isToSend: boolean } | null
  gone: string | null
}

const NOTHING_SETTLED: Settled = { held: null, gone: null }

/** Whether two gates state the same question over the same rows. */
const isSameGate = (gate: Gate | null, other: Gate | null) =>
  JSON.stringify(gate) === JSON.stringify(other)

/**
 * The gate a Bash result's stdout states directly above its menu, and that
 * stdout with the payload taken out, which is this module's input alone:
 * `text` keeps the menu as the engine wrote it, `cut` puts the instruction to
 * stop in its place. Null where the stdout states no gate.
 */
function gateIn(
  stdout: string,
): { gate: Gate; text: string; cut: string } | null {
  if (!stdout.includes(GATE_MARKER)) {
    return null
  }

  const lines = stdout.split('\n')
  const at = lines.findIndex(line => line.startsWith(GATE_MARKER))

  if (at === -1) {
    return null
  }

  const payload = lines[at + 1]
  const menu = lines[at + 2]

  if (payload === undefined || !(menu ?? '').startsWith(MENU_MARKER)) {
    return null
  }

  const { gate: name, ...gate } = JSON.parse(payload) as Gate & { gate: string }
  const before = lines.slice(0, at)
  const after = lines.findIndex(
    (line, n) => n > at + 2 && line.startsWith(SECTION_MARKER),
  )

  return {
    gate,
    text: [...before, ...lines.slice(at + 2)].join('\n'),
    cut: [
      ...before,
      `=== MENU: ${name} (drawn above the prompt — do NOT emit it; stop and wait) ===`,
      STOP_NOTE,
      ...(after === -1 ? [''] : lines.slice(after)),
    ].join('\n'),
  }
}

/**
 * The handoff a Bash result's stdout carries, and that stdout with its
 * payload taken out; null where it carries none.
 */
function handoffIn(stdout: string): { handoff: Handoff; text: string } | null {
  if (!stdout.includes(HANDOFF_MARKER)) {
    return null
  }

  const lines = stdout.split('\n')
  const at = lines.findIndex(line => line.startsWith(HANDOFF_MARKER))
  const payload = lines[at + 1]

  if (at === -1 || payload === undefined) {
    return null
  }

  const { text, line } = JSON.parse(payload) as Handoff

  return {
    handoff: { text, line },
    text: [...lines.slice(0, at), ...lines.slice(at + 2)].join('\n'),
  }
}

/**
 * Whether `version` is a release the mod runs on; one that does not read as
 * a release, a development build's included, counts as older.
 */
function isSupported(version: string): boolean {
  const release = RELEASE.exec(version)

  if (release === null) {
    return false
  }

  for (const [n, oldest] of OLDEST.entries()) {
    const part = Number(release[n + 1])

    if (part !== oldest) {
      return part > oldest
    }
  }

  return true
}

/**
 * Whether the mod applies to the session, read as the engine's boot reads
 * it: Claude Code's terminal app or the Desktop app's Code tab — one of the
 * mod's entrypoints, not Claude Code on the web — at a version the mod runs
 * on. Claude Code loads the mod wherever mods are on — the VS Code
 * extension's session, or an older Claude Code's with function hooks
 * switched on — so the check is the mod's own.
 */
async function isApplicable($: EngineInterface): Promise<boolean> {
  if (
    !ENTRYPOINTS.has((await $.env.get('CLAUDE_CODE_ENTRYPOINT')) ?? '') ||
    (await $.env.get('CLAUDE_CODE_REMOTE'))
  ) {
    return false
  }

  return isSupported((await $.session.version()).version)
}

/**
 * Whether the session announces the gate surface: set at its start, and
 * still set after a reload of the module. The band is kept and read back,
 * and the harness put on, only where it is, so a process whose session
 * never announced — one the mod does not apply to, or one this module was
 * loaded into after it started — never gets either.
 */
async function isAnnounced($: EngineInterface): Promise<boolean> {
  return (await $.env.get('WORKFLOWS_GATE_SURFACE')) === '1'
}

/** Whether an event is the conversation's own, not a subagent's loop. */
const inConversation = (e: AgentLoop) => e.agentId === undefined

/**
 * Whether the band takes a gate a Bash call stated: the conversation's own
 * call, not a subagent's; and the session's only screen the terminal or the
 * Desktop app, since the band is theirs and any other screen attached beside
 * it shows the menu as text alone. The Desktop app attaches after the
 * session starts, so this is read at the call.
 */
async function isForBand($: EngineInterface, e: AgentLoop): Promise<boolean> {
  if (!inConversation(e)) {
    return false
  }

  const [only, ...others] = await $.session.surfaces()

  return only !== undefined && others.length === 0 && BAND_SURFACES.has(only)
}

/**
 * Whether a submission is the person's: their Enter at the prompt, their
 * message through Remote Control, their message in the Desktop app — whose
 * Code tab runs the session as an SDK host, so it arrives as the host's own —
 * or this plugin sending their press. One with no origin is the person's
 * own, as the engine reads it.
 */
const isPersons = (origin: PromptOrigin | undefined, plugin: string) =>
  origin === undefined ||
  origin.kind === 'composer' ||
  origin.kind === 'bridge' ||
  origin.kind === 'sdk' ||
  (origin.kind === 'plugin' && origin.name === plugin)

/** The row a post names, or null when it names none of the gate's. */
function optionIn(gate: Gate, data: unknown): Option | null {
  const said = (data as { answer?: unknown } | null)?.answer

  return typeof said === 'string'
    ? (gate.options.find(option => answerOf(option) === said) ?? null)
    : null
}

/** Puts `text` in the prompt box in place of what is there; whether it took. */
async function fill($: EngineInterface, text: string): Promise<boolean> {
  const { isFilled } = await $.prompt.fill({ text, mode: 'replace' })

  return isFilled
}

/**
 * Sends the next message, the send recorded in the conversation's folder
 * where it has one; whether it entered. A send that fails or is dropped
 * leaves no send recorded.
 */
async function deliver($: EngineInterface, sent: Sent): Promise<boolean> {
  const folder = await folderOf($, await $.session.id())
  const record = async (text: string) => {
    if (folder !== null) {
      await $.fs.write(inFolder(folder, SENT), text)
    }
  }
  let isSent = false

  try {
    await record(JSON.stringify(sent))
    // Framed for the model and labelled on screen as this plugin's, by design.
    const { drop } = await $.prompt.submit({ text: sent.answer })

    isSent = drop === undefined
  } finally {
    if (!isSent) {
      await record(NOTHING_SENT)
    }
  }

  return isSent
}

/** Sends a row as the next message; whether it entered. */
const submit = ($: EngineInterface, gate: Gate, option: Option) =>
  deliver($, {
    answer: answerOf(option),
    question: gate.question,
    label: option.head,
  })

/** Whether `attempt` took; one that fails did not. */
const took = (attempt: Promise<boolean>) => attempt.catch(() => false)

/**
 * Carries a handoff: the conversation cleared, then the continuation sent into
 * the new one, recorded with its line in that conversation's folder first,
 * and a toast saying where the work went. A clear that fails sends in place,
 * so the work still goes on; a send that fails or is dropped waits in the
 * prompt box for Enter; where the box refuses it too, the toast holds the
 * continuation for the person to send.
 */
async function handOff($: EngineInterface, { text, line }: Handoff) {
  try {
    await $.command.run({ command: 'clear' })
  } catch {
    // Not cleared: the continuation goes on in this conversation.
  }

  const isCarried =
    (await took(deliver($, { answer: text, line }))) ||
    (await took(fill($, text)))

  if (isCarried) {
    $.ui.toast(`Handed off ${line}`)
  } else {
    $.ui.toast(`Not handed off ${line} — send this to carry on: ${text}`, {
      timeoutMs: UNCARRIED_TOAST_MS,
    })
  }
}

/**
 * Empties the prompt box while it holds exactly `text`, a pick's answer; a
 * draft the person has edited stays.
 */
async function unpick($: EngineInterface, text: string) {
  const box = await $.prompt.read()

  if (box.text === text) {
    await fill($, '')
  }
}

/**
 * Sends the picked row, the box cleared first; a send that fails or is
 * dropped puts the answer back in the box, where the pick says it is.
 */
async function send($: EngineInterface, gate: Gate, option: Option) {
  let isSent = false

  await fill($, '')

  try {
    isSent = await submit($, gate, option)
  } finally {
    if (!isSent) {
      await fill($, answerOf(option))
    }
  }
}

/**
 * Where a conversation stands: its session id, which names its folder, and
 * the stamp of the step its transcript ends on.
 */
type Place = { id: string; stamp: string }

/** What a conversation's folder keeps of its band: its gate, and where the transcript ended. */
type Kept = { stamp: string; gate: Gate }

/** A band read back from its folder: where the conversation stands, its gate. */
type ReadBack = { place: Place; gate: Gate | null }

/**
 * A read-back the band owes before it is trusted, never taken from `ended`:
 * the conversation that ended in this process, while the transcript still
 * holds it.
 */
type Owed = { ended: Place | null }

/** The tool calls a message makes or answers, by id. */
const callsOf = (message: SessionMessage) => [
  ...message.toolUses.map(use => use.tool_use_id),
  ...(message.toolResults ?? []).map(result => result.tool_use_id),
]

/**
 * The lines Claude Code writes around an interrupted turn rather than the
 * conversation taking a step: the interruption itself, which can land after
 * that turn's end has kept the band, and the reply it puts in the model's
 * place when the conversation is resumed after one. No stamp reads them.
 */
const isInterruption = (message: SessionMessage) =>
  (message.role === 'user' &&
    message.text.startsWith('[Request interrupted by user')) ||
  (message.role === 'assistant' &&
    message.text === 'No response requested.' &&
    message.toolUses.length === 0)

/**
 * Where the conversation stands now; null until it takes a step. The stamp
 * is the last step — who wrote it, its text, the calls it makes or answers —
 * and the newest call of all, so a conversation that moved on and came to
 * rest on the same words is told apart.
 */
async function placeOf($: EngineInterface): Promise<Place | null> {
  const id = await $.session.id()
  const steps = (await $.session.messages()).filter(
    message => !isInterruption(message),
  )
  const last = steps.at(-1)

  if (last === undefined) {
    return null
  }

  const calls = steps.flatMap(callsOf)

  return {
    id,
    stamp: JSON.stringify([
      last.role,
      last.text,
      callsOf(last),
      calls.at(-1) ?? null,
    ]),
  }
}

const isSamePlace = (place: Place, other: Place | null) =>
  other !== null && place.id === other.id && place.stamp === other.stamp

/** Whether `place` is the conversation `seen` read, however far on. */
const isSameConversation = (place: Place | null, seen: Place | null) =>
  place !== null && seen !== null && place.id === seen.id

const isKept = (value: unknown): value is Kept =>
  typeof value === 'object' &&
  value !== null &&
  typeof (value as Kept).stamp === 'string'

/**
 * The folder of the conversation `id`, which the engine names by the id's
 * safe characters alone, in the workflows' system config directory:
 * `WORKFLOWS_CONFIG_DIR`, else `.config/workflows` in the home directory.
 * Found by the id, so a `cd` or a resume elsewhere finds it all the same;
 * null where the process names neither directory.
 */
async function folderOf(
  $: EngineInterface,
  id: string,
): Promise<string | null> {
  const home = await $.env.get('HOME')
  const config =
    (await $.env.get('WORKFLOWS_CONFIG_DIR')) ||
    (home ? `${home}/.config/workflows` : null)

  return config === null
    ? null
    : `${config}/${CONVERSATIONS}/${id.replace(/[^A-Za-z0-9_-]/g, '')}`
}

/** A file in a conversation's folder. */
const inFolder = (folder: string, file: string) => `${folder}/${file}`

/**
 * The folder of the conversation `id` where the engine has marked it as one
 * that runs the workflows; null for any other conversation.
 */
async function markedFolder(
  $: EngineInterface,
  id: string,
): Promise<string | null> {
  const folder = await folderOf($, id)

  return folder !== null && (await $.fs.exists(inFolder(folder, MARKER)))
    ? folder
    : null
}

/**
 * Keeps what the band shows for the conversation at `place` — the gate, or
 * nothing — in its folder, in a session that announced and a conversation
 * that runs the workflows: any other conversation gets no folder.
 */
async function keep($: EngineInterface, place: Place | null, gate: Gate | null) {
  if (place === null || !(await isAnnounced($))) {
    return
  }

  const folder = await markedFolder($, place.id)

  if (folder === null) {
    return
  }

  const kept: Kept | null = gate === null ? null : { stamp: place.stamp, gate }

  await $.fs.write(inFolder(folder, KEPT), JSON.stringify(kept))
}

/** What `folder` keeps of its band; undefined where it keeps nothing readable. */
async function keptIn($: EngineInterface, folder: string): Promise<unknown> {
  try {
    return JSON.parse(await $.fs.read(inFolder(folder, KEPT)))
  } catch {
    return undefined
  }
}

/**
 * The person's own values of the settings the harness sets, absent where
 * unset: what the harness replaced, kept while it is on.
 */
type Replaced = {
  CLAUDE_CODE_THINKING_DISPLAY_UPDATES?: string
  CLAUDE_CODE_SILENT_TURN_REMINDER?: string
}

/**
 * Puts Claude Code's harness on for a workflow session, one whose
 * conversation the engine has marked in a session that announced: no
 * summary of Claude's thinking printed as if it were output, and no nudge to
 * say what it is doing. Claude Code reads both per request. What it replaces
 * is kept in the process's environment, which a reload of the module's files
 * keeps, and only where nothing is kept yet: the values are read before that
 * is looked at, so a harness another call has just put on is never kept as
 * the person's.
 */
async function harnessOn($: EngineInterface) {
  if (!(await isAnnounced($))) {
    return
  }

  const replaced: Replaced = {
    CLAUDE_CODE_THINKING_DISPLAY_UPDATES: await $.env.get(
      'CLAUDE_CODE_THINKING_DISPLAY_UPDATES',
    ),
    CLAUDE_CODE_SILENT_TURN_REMINDER: await $.env.get(
      'CLAUDE_CODE_SILENT_TURN_REMINDER',
    ),
  }

  if ((await $.env.get('WORKFLOWS_HARNESS_REPLACED')) === undefined) {
    await $.env.set('WORKFLOWS_HARNESS_REPLACED', JSON.stringify(replaced))
  }

  await $.env.set('CLAUDE_CODE_THINKING_DISPLAY_UPDATES', 'false')
  await $.env.set('CLAUDE_CODE_SILENT_TURN_REMINDER', 'false')
}

/**
 * Takes the harness off, putting back exactly what it replaced: the person's
 * value, or none. Where the harness is not on, nothing is touched.
 */
async function harnessOff($: EngineInterface) {
  const kept = await $.env.get('WORKFLOWS_HARNESS_REPLACED')

  if (kept === undefined) {
    return
  }

  const replaced = JSON.parse(kept) as Replaced

  await $.env.set(
    'CLAUDE_CODE_THINKING_DISPLAY_UPDATES',
    replaced.CLAUDE_CODE_THINKING_DISPLAY_UPDATES,
  )
  await $.env.set(
    'CLAUDE_CODE_SILENT_TURN_REMINDER',
    replaced.CLAUDE_CODE_SILENT_TURN_REMINDER,
  )
  await $.env.set('WORKFLOWS_HARNESS_REPLACED', undefined)
}

/**
 * Settles the read-back the band owes, if `owing` says it owes one: `take`
 * gets the conversation the transcript holds now, with its kept gate where
 * the transcript still ends where it was kept, or none where it has moved
 * on, the kept gate dropped while the read-back is still owed. A
 * conversation the engine has marked gets the workflow harness back, again
 * while the read-back is still owed. Nothing settles in a session that did
 * not announce, while the transcript is empty, or while it still holds the
 * conversation that ended in this process.
 */
async function readBack(
  $: EngineInterface,
  owing: () => Owed | null,
  take: (asked: Owed, read: ReadBack) => void,
) {
  const asked = owing()

  if (asked === null || !(await isAnnounced($))) {
    return
  }

  const place = await placeOf($)

  if (place === null || isSamePlace(place, asked.ended)) {
    return
  }

  const folder = await markedFolder($, place.id)

  if (folder !== null && owing() === asked) {
    await harnessOn($)
  }

  const kept = folder === null ? undefined : await keptIn($, folder)

  if (isKept(kept) && kept.stamp === place.stamp) {
    take(asked, { place, gate: kept.gate })

    return
  }

  if (folder !== null && isKept(kept) && owing() === asked) {
    await $.fs.write(inFolder(folder, KEPT), JSON.stringify(null))
  }

  take(asked, { place, gate: null })
}

export const register: Register = on => {
  let band = emptyBand()

  /** Whether a send is under way, so a press meanwhile cannot send twice. */
  let isSending = false

  /**
   * The read-back the band owes: from the module's load, which a restart or
   * a reload of its files begins, and from a conversation's end in this
   * process, until the next turn or a read settles it.
   */
  let owed: Owed | null = { ended: null }

  /** Where the conversation stood when the band was last kept or read back. */
  let seen: Place | null = null

  /** The handoff a call armed, carried once its turn ends. */
  let handoff: Handoff | null = null

  /**
   * Whether the clear under way is this module's own, for a handoff: the
   * conversation it leads into runs the workflows by construction, so the
   * workflow harness stays on through it.
   */
  let isClearingForHandoff = false

  /**
   * The person takes the turn: the band comes down, keeping the gate their
   * turn answers. Whether a gate came down.
   */
  const takeDown = (): boolean => {
    const { drawn } = band

    band = { ...emptyBand(), running: 'person', answering: drawn }

    return drawn !== null
  }

  /**
   * Settles the band as the conversation's turn ends. The person's turn
   * draws the gate it rendered; an Esc drops that and takes the answer back,
   * its gate returning, until the turn calls a tool, which may already have
   * acted on the answer: a read and a write look alike from here. Anyone
   * else's turn leaves the band as it is unless it rendered another gate: at
   * its end that gate takes the band and drops a held answer unsent; after an
   * Esc, which leaves the model at that gate's stop, the band empties. A held
   * answer on the gate still there sends now, or after an Esc goes back to
   * the prompt as a pick; a pick whose gate went goes with it.
   */
  const endTurn = (isInterrupted: boolean): Settled => {
    const { running, armed, drawn, picked, answering, hasCalledTool, sends } =
      band

    band = { ...band, armed: null, running: null, answering: null }

    if (running !== 'other') {
      band.drawn = isInterrupted ? (hasCalledTool ? null : answering) : armed

      return NOTHING_SETTLED
    }

    const gate = armed ?? drawn

    if (!isSameGate(gate, drawn)) {
      band = isInterrupted
        ? { ...band, drawn: null, picked: null, sends: NO_SENDS }
        : {
            ...band,
            drawn: gate,
            picked: null,
            sends: { held: null, dropped: sends.held },
          }

      return { held: null, gone: picked }
    }

    band.sends = { ...sends, held: null }

    const option =
      drawn === null || sends.held === null
        ? null
        : optionIn(drawn, { answer: sends.held })

    return {
      held: option === null ? null : { option, isToSend: !isInterrupted },
      gone: null,
    }
  }

  const owing = () => owed

  /**
   * Takes a read-back onto the band, unless a turn or a conversation's end
   * overtook it while it read: the conversation it read is the one the band
   * follows from here.
   */
  const takeBack = (asked: Owed, read: ReadBack) => {
    if (owed !== asked) {
      return
    }

    owed = null
    seen = read.place

    if (read.gate !== null) {
      band.drawn = read.gate
    }
  }

  // Announced, never always-on: the engine collects a gate, and composes a
  // handoff for this module to carry, only for a session that asked, and
  // every Bash child inherits this. Where the mod does not apply nothing is
  // announced, which leaves it inert there. A fresh load comes back to a
  // conversation this module has not followed, so the band is read back from
  // the conversation's folder.
  on('session.start', async ($, e, next) => {
    if (!(await isApplicable($))) {
      return next(e)
    }

    await $.env.set('WORKFLOWS_GATE_SURFACE', '1')
    await $.env.set('WORKFLOWS_HANDOFF', '1')

    // Claude Code builds its tool catalogue just after this hook, so only
    // here does the switch that gives the session SendUserMessage count.
    await $.env.set('CLAUDE_CODE_PEWTER_OWL_TOOL', 'true')

    owed = { ended: null }
    await readBack($, owing, takeBack)

    if (band.drawn !== null) {
      $.ui.invalidate('ui.render')
    }

    return next(e)
  }).catch(($, e, next) => next(e))

  // A /clear or a resume goes on in this process as another conversation,
  // which no gate of this one answers and which is no workflow session until
  // the engine marks it or it is read back as one it has marked. What the
  // band showed is kept for this one first, stamped where its transcript
  // ends now, which can have moved since its last turn's end. The clear a
  // handoff runs leads into a workflow conversation, so the harness stays on.
  on('session.end', async ($, e, next) => {
    const isHandingOff = isClearingForHandoff && e.reason === 'clear'

    isClearingForHandoff = false

    try {
      const place = await placeOf($)

      if (isSameConversation(place, seen)) {
        await keep($, place, band.drawn)
        seen = place
      }
    } finally {
      band = emptyBand()
      handoff = null
      owed = { ended: seen }
      seen = null
      $.ui.invalidate('ui.render')

      if (!isHandingOff) {
        await harnessOff($)
      }
    }

    return next(e)
  }).catch(($, e, next) => next(e))

  on('tool.call', ($, e, next) => {
    if (inConversation(e)) {
      band.hasCalledTool = true
    }

    return next(e)
  }).catch(($, e, next) => next(e))

  // Every engine call marks the conversation that made it, whatever its exit,
  // so after each of the conversation's own commands the mark says whether it
  // runs the workflows; a command that only mentions the engine marks nothing.
  // A failure replays the payloads uncut, so the harness never fails the call
  // and nothing is armed until nothing more can fail.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const result = await next(e)

    try {
      if (
        inConversation(e) &&
        (await markedFolder($, await $.session.id())) !== null
      ) {
        await harnessOn($)
      }
    } catch {
      // The harness waits for the conversation's next call.
    }

    if (result.deny !== undefined || result.isError === true) {
      return result
    }

    const record = result.result
    const carried = handoffIn(record.stdout)
    const stdout = carried === null ? record.stdout : carried.text
    const stated = gateIn(stdout)
    const isArmed = stated !== null && (await isForBand($, e))

    if (carried !== null && inConversation(e)) {
      handoff = carried.handoff
    }

    if (stated === null) {
      return carried === null ? result : { result: { ...record, stdout } }
    }

    if (isArmed) {
      band.armed = stated.gate
    }

    return {
      result: { ...record, stdout: isArmed ? stated.cut : stated.text },
    }
  }).catch(($, e, next) => next(e))

  // The tool waits behind ToolSearch in every session that announced,
  // workflow or not: one answer, since a changed answer sends the tool list
  // again and spends the prompt cache.
  on('tool.describe', { tool: 'SendUserMessage' }, async ($, e, next) => {
    const described = await next(e)

    return (await isAnnounced($))
      ? { ...described, isDeferred: true }
      : described
  }).catch(($, e, next) => next(e))

  // Drawn at the turn's end, once what the rows choose between is on screen,
  // and kept with where the transcript ends, which a resume must still match.
  // A held answer is not kept: it waits on a turn no resume brings back. It
  // sends once the turn is over, and one not sent is put back as a pick; the
  // answer of a pick whose gate went leaves the prompt box. A handoff the turn
  // armed is carried once it is over, whatever else at its end fails; an Esc
  // means stop, and carries nothing.
  on('turn.complete', async ($, e, next) => {
    if (!inConversation(e)) {
      return next(e)
    }

    const carried = handoff

    handoff = null

    try {
      const settled = endTurn(e.isAborted)
      const { drawn } = band

      owed = null

      if (drawn !== null) {
        $.ui.invalidate('ui.render')
      }

      const place = await placeOf($)

      await keep($, place, drawn)
      seen = place

      const answered = await next(e)
      const { held, gone } = settled

      if (gone !== null) {
        await unpick($, gone)
      }

      if (held !== null && drawn !== null) {
        const answer = answerOf(held.option)
        let isSent = false

        isSending = true

        try {
          isSent = held.isToSend && (await submit($, drawn, held.option))
        } finally {
          isSending = false

          if (!isSent && (await fill($, answer))) {
            band.picked = answer
            $.ui.invalidate('ui.render')
          }
        }
      }

      return answered
    } finally {
      if (carried !== null && !e.isAborted) {
        // A command cannot run inside a hook the turn waits on, so the clear
        // runs from a timer once this hook is done — proven in the lab.
        $.clock.after(0, () => {
          isClearingForHandoff = true
          void handOff($, carried).finally(() => {
            isClearingForHandoff = false
          })
        })
      }
    }
  }).catch(($, e, next) => next(e))

  // A drawing while a read-back is owed — a reload's first, the first after
  // a conversation's end, one before the transcript was there to read —
  // settles it first.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    await readBack($, owing, takeBack)

    const gate = band.drawn

    if (
      gate === null ||
      e.props.hasSurvey ||
      (e.surface !== 'terminal' && e.surface !== 'desktop')
    ) {
      return next(e)
    }

    const beneath = await next(e)

    try {
      const { Box, Client } = await $.ui.resolve(e)
      const { bodyColumns: columns, maxRows } = e.props

      return Box({
        flexDirection: 'column',
        children: [
          // The module's path is read off this source, so it is a literal;
          // the region must be exactly as tall as the drawing, or the pointer
          // cannot reach the rows past its edge.
          h(Client, {
            key: ELEMENT,
            module: './board.ts',
            width: columns,
            height: linesOf(gate, columns, IDLE, band.sends, maxRows).length,
            props: {
              gate,
              picked: band.picked,
              ...band.sends,
              columns,
              maxRows,
            },
          }),
          beneath,
        ],
      })
    } catch {
      return beneath
    }
  }).catch(($, e, next) => next(e))

  // The board has no `$`: a press posts here, and this picks its row or, on
  // the row already picked, sends it. The turn a send opens takes the gate
  // off the band; a send that fails or is dropped leaves the row there to
  // press again. While anyone else's turn runs, the send is held, its answer
  // out of the prompt box, until that turn ends; a press on the held row
  // takes it back to a pick, and a press on another row picks that instead.
  on('ui.message', { element: ELEMENT }, async ($, e, next) => {
    const gate = band.drawn
    const option = gate === null || isSending ? null : optionIn(gate, e.data)

    if (gate === null || option === null) {
      return next(e)
    }

    const answer = answerOf(option)

    if (answer !== band.picked) {
      if (await fill($, answer)) {
        band.picked = answer
        band.sends = { ...band.sends, held: null }
        $.ui.invalidate('ui.render')
      }
    } else if (band.running === 'other') {
      if (await fill($, '')) {
        band.picked = null
        band.sends = { ...band.sends, held: answer }
        $.ui.invalidate('ui.render')
      }
    } else {
      isSending = true

      try {
        await send($, gate, option)
      } finally {
        isSending = false
      }
    }

    return next(e)
  }).catch(($, e, next) => next(e))

  // A submission made while the session idles opens the next turn; one made
  // over a running turn joins it, and the person's makes anyone else's turn
  // theirs, which takes the band down.
  on('prompt.submit', ($, e, next) => {
    const isTheirs = isPersons(e.origin, $.plugin.name)

    if (e.turnId === undefined) {
      band.isOpenedByPerson = isTheirs
    } else if (isTheirs && band.running === 'other') {
      if (takeDown()) {
        $.ui.invalidate('ui.render')
      }
    }

    return next(e)
  }).catch(($, e, next) => next(e))

  // A gate lives from its render to the turn the person starts to answer it,
  // which keeps it to put back; a gate the conversation re-presents is armed
  // again by its own render. Anyone else's turn — an agent's report, a
  // notification, a schedule — leaves the band live, its rows still to
  // press. The band follows the conversation the turn runs in, owing no
  // read-back.
  on('turn.start', ($, e, next) => {
    owed = null

    if (!band.isOpenedByPerson) {
      band = {
        ...band,
        armed: null,
        isOpenedByPerson: true,
        running: 'other',
        hasCalledTool: false,
      }
    } else if (takeDown()) {
      $.ui.invalidate('ui.render')
    }

    return next(e)
  }).catch(($, e, next) => next(e))
}

files.hooks/layout.ts:
/**
 * The gate's geometry and text shaping, shared by the hooks module and the
 * board: the band is one list of lines, which the hook counts to size the
 * `Client`'s region and the board draws line for line. Any drift between the
 * two is dead space under the last row, or rows the pointer cannot reach.
 *
 * The engine states every gate as data, so nothing here parses markdown: a
 * row arrives already split into what it is and what it says about itself.
 */

/** One pressable row of the engine's gate payload. */
export type Option = {
  key: string
  word: string | null
  head: string
  tail: string | null
  cue: string | null
  holder: string | null
  detail: string | null
  struck: boolean
  recommended: boolean
}

/** One row of the payload a span or a natural reply can only answer. */
export type Typed = {
  label: string
  description: string
  detail: string | null
}

/** A gate as the engine states it, less its name. */
export type Gate = {
  question: string
  statement: string
  options: Option[]
  typed: Typed[]
}

/** A run of a drawn line under one style. */
export type Run = {
  text: string
  bold?: boolean
  dim?: boolean
  italic?: boolean
  strikethrough?: boolean
  underline?: boolean
  /** Drawn in the colour the band asks in, rather than the text's own. */
  accent?: boolean
}

/**
 * What the footer says: how to answer, what a pick put in the prompt, what
 * waits to send when Claude finishes, what a new gate kept from sending, or
 * how to answer the typed row last clicked.
 */
export type Footer =
  | { kind: 'idle' }
  | { kind: 'picked'; answer: string }
  | { kind: 'queued'; answer: string }
  | { kind: 'dropped'; answer: string }
  | { kind: 'typed'; label: string }

/**
 * What became of a send pressed while Claude works: the answer held until it
 * finishes, and one a new gate kept from sending, which that gate's footer
 * names.
 */
export type Sends = { held: string | null; dropped: string | null }

/**
 * A line of a row: its wrapped label or its detail, each carrying the row so
 * a pointer lands on any of them. The key column, filled on the first line
 * alone, and the label are padded out so a background spans the band.
 */
export type RowLine = {
  kind: 'option' | 'typed'
  index: number
  key: Run[]
  runs: Run[]
}

/** The line under a page of rows: which page shows, of how many. */
export type PagerLine = { kind: 'pager'; page: number; pages: number }

/** One line of the band, top to bottom. */
export type Line =
  | { kind: 'rule' }
  | { kind: 'blank' }
  | { kind: 'prose'; glyph: boolean; runs: Run[] }
  | RowLine
  | PagerLine
  | { kind: 'footer'; runs: Run[] }

/** The cursor's gutter, where the footer also sits. */
export const GUTTER = 2

/** The `◆ ` the question opens with; the statement lines up past it. */
export const GLYPH_COLUMN = 2

export const IDLE: Footer = { kind: 'idle' }

export const NO_SENDS: Sends = { held: null, dropped: null }

const GAP = 2
const MIN_LABEL = 8

const TAIL_SEPARATOR = ' — '
const NOTE_SEPARATOR = ' · '
const RECOMMENDED = ' (recommended)'
const QUEUED = ' · queued'

const IDLE_HINT = 'Click to choose · click again to send · or type'
const PICKED_HINT = ' is in your prompt · click again to send'
const QUEUED_HINT = ' sends when Claude finishes · click to undo'
const DROPPED_HINT = ' not sent — the menu changed'

const PREVIOUS = '↑ previous'
const NEXT = '↓ next'
const PAGER_GAP = '   '

/** A typed row's label that is a span of numbers, as the engine writes one. */
const RANGE = /^\d+–\d+$/

const RULE: Line = { kind: 'rule' }
const BLANK: Line = { kind: 'blank' }

/** The cells of the pager line its previous and next presses cover. */
export const PAGER_SPANS = {
  previous: { from: GUTTER, to: GUTTER + PREVIOUS.length },
  next: {
    from: GUTTER + PREVIOUS.length + PAGER_GAP.length,
    to: GUTTER + PREVIOUS.length + PAGER_GAP.length + NEXT.length,
  },
}

/** What a row shows in its key column, and what pressing it answers with. */
export const answerOf = (option: Option) => option.word ?? option.key

/**
 * The row the cursor starts on, so Enter on arrival takes what the engine
 * recommends: that row, else the first not struck through, else the first.
 */
export function startingRow(options: readonly Option[]): number {
  const recommended = options.findIndex(option => option.recommended)

  return recommended !== -1
    ? recommended
    : Math.max(0, options.findIndex(option => !option.struck))
}

/** Fills a line out to `width`, so a background spans it. */
export function pad(runs: readonly Run[], width: number): Run[] {
  const short = width - runs.reduce((cells, run) => cells + run.text.length, 0)

  return short > 0 ? [...runs, { text: ' '.repeat(short) }] : [...runs]
}

/**
 * Greedy word wrap that keeps each run's styling: a label too long for its
 * column breaks onto the next line rather than being cut, so nothing the
 * engine wrote is lost. A line's words come back under one run per style,
 * and the space a break falls on is dropped rather than drawn.
 */
export function wrapRuns(runs: readonly Run[], width: number): Run[][] {
  const column = Math.max(1, width)
  const lines: Run[][] = []

  let line: { source: Run; run: Run }[] = []
  let used = 0
  let gap: { source: Run; text: string } | null = null

  const wrap = () => {
    lines.push(line.map(entry => entry.run))
    line = []
    used = 0
    gap = null
  }

  const add = (source: Run, text: string) => {
    const last = line.at(-1)

    if (last !== undefined && last.source === source) {
      last.run.text += text
    } else {
      line.push({ source, run: { ...source, text } })
    }

    used += text.length
  }

  for (const source of runs) {
    for (const piece of source.text.split(/(\s+)/)) {
      if (piece === '') {
        continue
      }

      if (piece.trim() === '') {
        gap = used > 0 ? { source, text: piece } : null
        continue
      }

      let word = piece

      while (word.length > column) {
        if (used > 0) {
          wrap()
        }

        add(source, word.slice(0, column))
        word = word.slice(column)
        wrap()
      }

      if (used > 0 && used + (gap?.text.length ?? 0) + word.length > column) {
        wrap()
      } else if (gap !== null) {
        add(gap.source, gap.text)
      }

      gap = null
      add(source, word)
    }
  }

  if (line.length > 0 || lines.length === 0) {
    wrap()
  }

  return lines
}

/** Text whose lines are its own, each wrapped to `width`; none for no text. */
const paragraphs = (
  text: string,
  width: number,
  style: Omit<Run, 'text'> = {},
) =>
  text === ''
    ? []
    : text
        .split('\n')
        .flatMap(line => wrapRuns([{ ...style, text: line }], width))

/**
 * The band's two columns at this width: the keys, and the labels beside
 * them. The band has no frame, so a row is gutter, key, gap, label.
 */
export function geometry(gate: Gate, columns: number) {
  const keyWidth = Math.max(
    1,
    ...gate.options.map(option => answerOf(option).length),
    ...gate.typed.map(row => row.label.length),
  )

  return {
    keyWidth,
    labelWidth: Math.max(MIN_LABEL, columns - GUTTER - keyWidth - GAP),
  }
}

/**
 * The key column's runs: the word with the row's key underlined where the
 * word spells it, as a menu marks its accelerator; a bare key as it is.
 */
function keyRuns(option: Option): Run[] {
  const shown = answerOf(option)
  const at =
    option.word === null
      ? -1
      : shown.toLowerCase().indexOf(option.key.toLowerCase())

  if (at === -1) {
    return [{ text: shown }]
  }

  const end = at + option.key.length

  return [
    { text: shown.slice(0, at) },
    { text: shown.slice(at, end), underline: true },
    { text: shown.slice(end) },
  ].filter(run => run.text !== '')
}

/** A label part after its separator; nothing for a part the row lacks. */
const partRuns = (
  separator: string,
  text: string | null,
  style: Omit<Run, 'text'> = {},
): Run[] => (text === null ? [] : [{ text: `${separator}${text}`, ...style }])

/**
 * A row's label by the text menu's grammar: the tail dim and italic after a
 * dash, and a cue the same after a dot; a held row struck from its head
 * through its cue, the holder plain after the strike; and the recommendation
 * last, bold in the accent colour.
 */
function labelRuns(option: Option): Run[] {
  const strike = option.struck ? { strikethrough: true } : {}
  const aside = { ...strike, dim: true, italic: true }

  return [
    { text: option.head, ...strike },
    ...partRuns(TAIL_SEPARATOR, option.tail, aside),
    ...partRuns(NOTE_SEPARATOR, option.cue, aside),
    ...partRuns(NOTE_SEPARATOR, option.holder),
    ...(option.recommended
      ? [{ text: RECOMMENDED, bold: true, accent: true }]
      : []),
  ]
}

/**
 * The pressable rows and then the typed ones, each row's lines a group
 * closed by its detail; every pressable row marked queued after its label
 * where `queued`.
 */
function rowGroups(gate: Gate, columns: number, queued: boolean): RowLine[][] {
  const { keyWidth, labelWidth } = geometry(gate, columns)

  const linesOfRow = (
    kind: RowLine['kind'],
    index: number,
    key: Run[],
    label: Run[],
    detail: string | null,
  ): RowLine[] =>
    [
      ...wrapRuns(label, labelWidth),
      ...paragraphs(detail ?? '', labelWidth, { dim: true }),
    ].map((runs, n) => ({
      kind,
      index,
      key: pad(n === 0 ? key : [], keyWidth + GAP),
      runs: pad(runs, labelWidth),
    }))

  return [
    ...gate.options.map((option, index) =>
      linesOfRow(
        'option',
        index,
        keyRuns(option),
        [...labelRuns(option), ...(queued ? [{ text: QUEUED }] : [])],
        option.detail,
      ),
    ),
    ...gate.typed.map((row, index) =>
      linesOfRow(
        'typed',
        index,
        [{ text: row.label, dim: true }],
        [{ text: row.description, dim: true }],
        row.detail,
      ),
    ),
  ]
}

// A click leaves the keys with the band; only the person can hand them back.
const typedHint = (label: string) =>
  RANGE.test(label)
    ? `${label} — Esc, then type the numbers in the prompt`
    : `${label} — Esc, then type it in the prompt`

/** The footer's words: dim, the answer it speaks of named in bold. */
export function footerRuns(footer: Footer): Run[] {
  switch (footer.kind) {
    case 'idle':
      return [{ text: IDLE_HINT, dim: true }]
    case 'picked':
      return [
        { text: footer.answer, bold: true },
        { text: PICKED_HINT, dim: true },
      ]
    case 'queued':
      return [
        { text: footer.answer, bold: true },
        { text: QUEUED_HINT, dim: true },
      ]
    case 'dropped':
      return [
        { text: footer.answer, bold: true },
        { text: DROPPED_HINT, dim: true },
      ]
    case 'typed':
      return [{ text: typedHint(footer.label), dim: true }]
  }
}

const footerLines = (footer: Footer, columns: number) =>
  wrapRuns(footerRuns(footer), columns - GUTTER)

/**
 * The footer, in a slot as tall as the tallest thing it can say for this
 * gate, so a click never moves the rows above it.
 */
function footerSlot(
  gate: Gate,
  footer: Footer,
  columns: number,
  dropped: string | null,
): Line[] {
  const states: Footer[] = [
    IDLE,
    ...gate.options.flatMap(option => [
      { kind: 'picked' as const, answer: answerOf(option) },
      { kind: 'queued' as const, answer: answerOf(option) },
    ]),
    ...gate.typed.map(row => ({ kind: 'typed' as const, label: row.label })),
    ...(dropped === null
      ? []
      : [{ kind: 'dropped' as const, answer: dropped }]),
  ]

  const rows = Math.max(
    ...states.map(state => footerLines(state, columns).length),
  )
  const said = footerLines(footer, columns)

  return Array.from({ length: rows }, (_, n) => ({
    kind: 'footer',
    runs: said[n] ?? [],
  }))
}

/**
 * The rows cut into pages of `budget` lines, in order: a page takes whole
 * rows while they fit, and a row taller than a page is cut to it.
 */
function pagesOf(groups: readonly RowLine[][], budget: number): RowLine[][] {
  const pages: RowLine[][] = []
  let page: RowLine[] = []

  for (const group of groups) {
    const lines = group.slice(0, budget)

    if (page.length > 0 && page.length + lines.length > budget) {
      pages.push(page)
      page = []
    }

    page = [...page, ...lines]
  }

  return [...pages, page]
}

/** The page holding the option at `cursor`; the first for none. */
const pageHolding = (pages: readonly RowLine[][], cursor: number) =>
  Math.max(
    0,
    pages.findIndex(page =>
      page.some(line => line.kind === 'option' && line.index === cursor),
    ),
  )

/**
 * Every line the band draws for a gate, top to bottom: the rule, a blank, the
 * statement, the question, a blank, the rows, a blank and the footer. Where
 * that would stand taller than `maxRows`, the rows show a page at a time over
 * a pager line, every page padded to one height; the page shown is `page`, or
 * the one holding the option at `cursor`. How many lines there are is the
 * region's height whatever the footer says, whichever row is held and
 * whichever page shows.
 */
export function linesOf(
  gate: Gate,
  columns: number,
  footer: Footer = IDLE,
  { held, dropped }: Sends = NO_SENDS,
  maxRows = Infinity,
  { page, cursor = -1 }: { page?: number; cursor?: number } = {},
): Line[] {
  const width = columns - GLYPH_COLUMN
  const statement = paragraphs(gate.statement, width)
  const question = paragraphs(gate.question, width, { bold: true })
  const prose = (runs: Run[], glyph: boolean): Line => ({
    kind: 'prose',
    glyph,
    runs,
  })

  const plain = rowGroups(gate, columns, false)
  const queued = rowGroups(gate, columns, true)
  const heldAt = gate.options.findIndex(option => answerOf(option) === held)
  const groups = plain.map((group, n) =>
    n === heldAt ? (queued[n] ?? group) : group,
  )
  const rows = groups.flat()
  const marks = queued.map((group, n) => group.length - (plain[n]?.length ?? 0))
  const tallest = plain.flat().length + Math.max(0, ...marks)
  const head: Line[] = [
    RULE,
    BLANK,
    ...statement.map(runs => prose(runs, false)),
    ...question.map((runs, n) => prose(runs, n === 0)),
    BLANK,
  ]
  const foot = [BLANK, ...footerSlot(gate, footer, columns, dropped)]
  // Lines under the footer that the rows take back when a held row's mark
  // wraps, so the whole gate holds its height.
  const spare = Array.from(
    { length: tallest - rows.length },
    (): Line => ({ kind: 'footer', runs: [] }),
  )
  const whole = [...head, ...rows, ...foot, ...spare]

  if (whole.length <= maxRows) {
    return whole
  }

  const budget = Math.max(1, maxRows - head.length - 1 - foot.length)
  const pages = pagesOf(groups, budget)
  const shown = Math.min(pages.length - 1, page ?? pageHolding(pages, cursor))
  const lines: Line[] = pages[shown] ?? []

  return [
    ...head,
    ...lines,
    ...Array.from({ length: budget - lines.length }, () => BLANK),
    { kind: 'pager', page: shown, pages: pages.length },
    ...foot,
  ]
}

/** The pager line's words, a press that goes nowhere dim. */
export const pagerRuns = ({ page, pages }: PagerLine): Run[] => [
  { text: PREVIOUS, dim: page === 0 },
  { text: PAGER_GAP },
  { text: NEXT, dim: page === pages - 1 },
  { text: `${PAGER_GAP}page ${page + 1} of ${pages}`, dim: true },
]

/** The page the option at `cursor` shows on; the first where none pages. */
export const pageOf = (
  gate: Gate,
  columns: number,
  sends: Sends,
  maxRows: number,
  cursor: number,
) =>
  linesOf(gate, columns, IDLE, sends, maxRows, { cursor }).find(
    (line): line is PagerLine => line.kind === 'pager',
  )?.page ?? 0

/** The first option on `page`; null where the page shows none. */
export const firstOnPage = (
  gate: Gate,
  columns: number,
  sends: Sends,
  maxRows: number,
  page: number,
) =>
  linesOf(gate, columns, IDLE, sends, maxRows, { page }).find(
    (line): line is RowLine => line.kind === 'option',
  )?.index ?? null

